def create_frequency_tables(document, n):
    """
    This function constructs a list of `n` frequency tables for an n-gram model, each table capturing character frequencies with increasing conditional dependencies.

    - **Parameters**:
        - `document`: The text document used to train the model.
        - `n`: The number of value of `n` for the n-gram model.

    - **Returns**:
        - Returns a list of n frequency tables.
    """

    tables = [{} for _ in range(n)] # list of n empty dicts (dict = table)
    for i in range(len(document)):
        for j in range(1, n + 1):
            if i - j + 1 >= 0:
                ctxt = document[i - j + 1:i] # ctxt = context
                curr_char = document[i]

                table = tables[j - 1]

                if curr_char not in table:
                    table[curr_char] = {}

                if context not in table[curr_char]:
                    table[curr_char][ctxt] = 0

                table[curr_char][ctxt] += 1

    return tables


