class Autocomplete():
    def __init__(self, parent=None, document=""):
        self.root = Node()
        self.suggest = self.suggest_ucs

    def build_tree(self, document):
        frequency = defaultdict(int)
        for word in document.split():
            for index in range(len(word)):
                for char in word[index + 1:]:
                    frequency[(word[index], char)] += 1
        for word in document.split():
            node = self.root
            for char in word:
                if char not in node.children:
                    node.children[char] = Node()
                node = node.children[char]
                following_chars = [ch for ch in node.children.keys()]
                if following_chars:
                    for following_char in following_chars:
                        inverse_frequency = 1 / (frequency[(char, following_char)] + 1)
                        node.path_cost += inverse_frequency
            node.is_word = True

    def suggest_random(self, prefix):
        random_suffixes = [''.join(random.choice(string.ascii_lowercase) for _ in range(3)) for _ in range(5)]
        return [prefix + suffix for suffix in random_suffixes]

    def suggest_bfs(self, prefix):
        node = self.root
        for char in prefix:
            if char in node.children:
                node = node.children[char]
            else:
                return []
        words = []
        queue = deque([(node, prefix)])
        while queue:
            (current_node, current_prefix) = queue.popleft()
            if current_node.is_word:
                words.append(current_prefix)
            for char, child_node in current_node.children.items():
                queue.append((child_node, current_prefix + char))
        return words


    def suggest_dfs(self, prefix):
        suggestions = []
        def dfs(node, current_prefix):
            if node.is_word:
                suggestions.append(current_prefix)
            for char, child_node in node.children.items():
                dfs(child_node, current_prefix + char)
        node = self.root
        for char in prefix:
            if char in node.children:
                node = node.children[char]
            else:
                return []
        dfs(node, prefix)
        return suggestions

    def suggest_ucs(self, prefix):
        node = self.root
        for char in prefix:
            if char in node.children:
                node = node.children[char]
            else:
                return []
        priority_queue = []
        heapq.heappush(priority_queue, (0, prefix, node))
        suggestions = []
        while priority_queue:
            cost, current_prefix, current_node = heapq.heappop(priority_queue)
            if current_node.is_word:
                suggestions.append(current_prefix)
            for char, child_node in current_node.children.items():
                new_cost = cost + child_node.path_cost
                new_prefix = current_prefix + char
                heapq.heappush(priority_queue, (new_cost, new_prefix, child_node))
        return suggestions

